WITH filtered AS (SELECT id, store_id, product_id, quantity, last_restock, CAST(quantity AS STRING) quantity_str FROM inventory WHERE last_restock >= DATE '2023-05-14') SELECT CASE WHEN quantity >= 227 THEN 'LARGE' ELSE 'SMALL' END AS quantity_tier, BIT_AND(quantity) AS quantity_bit_and, PERCENTILE_APPROX(quantity, 0.95) AS quantity_p95, COUNT(*) AS event_count, BIT_AND(quantity) AS quantity_bit_and_2, COUNT(*) AS row_count, GROUPING_ID() AS grouping_id FROM filtered GROUP BY ROLLUP (CASE WHEN quantity >= 227 THEN 'LARGE' ELSE 'SMALL' END) ORDER BY quantity_bit_and_2 DESC
